import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
capacity_records = [r for r in records if r['source'] == 'capacity.csv']
if not capacity_records or 'Capacity' not in capacity_records[0]['values']:
    raise ValueError('Missing capacity in LEGACY_RECORDS')
capacity = int(capacity_records[0]['values']['Capacity'])
product_records = [r for r in records if r['source'] == 'products.csv']
products = []
value = {}
weight = {}
for r in product_records:
    pname = r['values']['ProductName']
    if pname in products:
        raise ValueError(f'Duplicate product: {pname}')
    products.append(pname)
    if 'Value' not in r['values'] or 'Weight' not in r['values']:
        raise ValueError(f'Missing Value or Weight for product {pname}')
    value[pname] = int(r['values']['Value'])
    weight[pname] = int(r['values']['Weight'])
if len(products) != len(value) or len(products) != len(weight):
    raise ValueError('Mismatch in product, value, or weight dimensions')
m = gp.Model('vehicle_inventory')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[i] * x[i] for i in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in products)) <= capacity, name='cap')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')